   773→                      </div>
   774→                    )}
   775→                  </Form.Group>
   776→                )}
   777→
   778→                {/* Uploaded File Display */}
   779→                {uploadedMedia && (
   780→                  <Alert variant="success" className="py-2 mb-3">
   781→                    <div className="d-flex justify-content-between align-items-center">
   782→                      <div>
