/**
 * Download Excel template for bulk upload
 * @param {Array<Object>} variables - Optional array of template variables to include as columns
 *                                    Each variable should have { name, example }
 */
downloadTemplate(variables = []) {
  // Create a new workbook
  const wb = XLSX.utils.book_new();

  // Build headers: base columns + variable columns
  const headers = ['Número de Teléfono', 'Nombre (Opcional)'];
  const exampleRow1 = ['+57 300 1234567', 'Juan Pérez'];
  const exampleRow2 = ['+34 612 345 678', 'María García'];
  const exampleRow3 = ['+1 555 123 4567', 'John Smith'];

  // Add variable columns if provided
  if (variables.length > 0) {
    variables.forEach(variable => {
      headers.push(variable.name);
      exampleRow1.push(variable.example || `Ejemplo ${variable.name}`);
      exampleRow2.push(variable.example || `Ejemplo ${variable.name}`);
      exampleRow3.push(variable.example || `Ejemplo ${variable.name}`);
    });
  }

  // Create data with header and examples
  const data = [headers, exampleRow1, exampleRow2, exampleRow3];

  // Create worksheet
  const ws = XLSX.utils.aoa_to_sheet(data);

  // Set column widths
  const colWidths = [
    { wch: 25 },  // Column A (Número de Teléfono)
    { wch: 30 }   // Column B (Nombre)
  ];
  // Add width for variable columns
  variables.forEach(() => {
    colWidths.push({ wch: 25 });
  });
  ws['!cols'] = colWidths;

  // Total columns count
  const totalCols = 2 + variables.length;

  // Format all cells as text to prevent Excel auto-formatting
  const range = XLSX.utils.decode_range(ws['!ref']);

  for (let row = range.s.r; row <= range.e.r; row++) {
    for (let col = range.s.c; col <= range.e.c; col++) {
      const cellAddress = XLSX.utils.encode_cell({ r: row, c: col });

      if (!ws[cellAddress]) continue;

      // Ensure cell is treated as text
      ws[cellAddress].t = 's'; // Set type as string
      ws[cellAddress].z = '@'; // Set number format as text
    }
  }

  // Add empty rows pre-formatted as text for users to fill
  for (let row = 4; row <= 53; row++) { // Add 50 empty rows
    for (let col = 0; col < totalCols; col++) {
      const cellAddress = XLSX.utils.encode_cell({ r: row, c: col });
      ws[cellAddress] = {
        t: 's',  // String type
        v: '',   // Empty value
        z: '@'   // Text format
      };
    }
  }

  // Update the range to include empty rows and all columns
  ws['!ref'] = XLSX.utils.encode_range({
    s: { r: 0, c: 0 },
    e: { r: 53, c: totalCols - 1 }
  });

  // Add worksheet to workbook
  XLSX.utils.book_append_sheet(wb, ws, 'Receptores');

  // Generate file name with timestamp
  const timestamp = new Date().toISOString().split('T')[0];
  const suffix = variables.length > 0 ? '_con_variables' : '';
  const fileName = `plantilla_carga_masiva${suffix}_${timestamp}.xlsx`;

  // Download file with cell format settings
  XLSX.writeFile(wb, fileName, {
    bookType: 'xlsx',
    cellStyles: true
  });
},

