  /**
   * Parse CSV/Excel/TXT file for recipients
   *
   * @param {File} file - CSV, XLSX, or TXT file
   * @param {Array<string>} expectedVariables - Optional array of expected variable names
   * @returns {Promise<Object>} Object with recipients array and validation info
   *   - recipients: Array<{ phone, name, variables?: Object }>
   *   - errors: Array<{ row, message }> - validation errors
   *   - warnings: Array<string> - non-blocking warnings
   */
  async parseRecipientsFile(file, expectedVariables = []) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();

      reader.onload = (event) => {
        try {
          const recipients = [];
          const errors = [];
          const warnings = [];
          const fileName = file.name.toLowerCase();
          let variableColumnIndices = {}; // Maps variable name to column index

          // Check if it's an Excel file
          if (fileName.endsWith('.xlsx') || fileName.endsWith('.xls')) {
            // Parse Excel file
            const data = new Uint8Array(event.target.result);
            const workbook = XLSX.read(data, { type: 'array' });

            // Get first sheet
            const firstSheet = workbook.Sheets[workbook.SheetNames[0]];

            // Convert to JSON
            const rows = XLSX.utils.sheet_to_json(firstSheet, { header: 1 });

            console.log('Excel rows:', rows);

            // If we expect variables, find their column indices from header row
            if (expectedVariables.length > 0 && rows.length > 0) {
              const headerRow = rows[0].map(h => String(h || '').trim());

              // Check for missing columns
              const missingColumns = [];
              expectedVariables.forEach(varName => {
                const colIndex = headerRow.findIndex(h =>
                  h.toLowerCase() === varName.toLowerCase()
                );
                if (colIndex === -1) {
                  missingColumns.push(varName);
                } else {
                  variableColumnIndices[varName] = colIndex;
                }
              });

              if (missingColumns.length > 0) {
                reject(new Error(`Columnas faltantes en el Excel: ${missingColumns.join(', ')}`));
                return;
              }
            }

            // Process rows (skip first row which is the header)
            rows.forEach((row, index) => {
              // Skip header row (first row, index 0)
              if (index === 0) return;

              if (!row || row.length === 0) return; // Skip empty rows

              // Get phone from first column
              let phone = String(row[0] || '').trim();

              // Skip if phone is empty
              if (!phone) return;

              // Clean phone number
              phone = phone
                .replace(/["']/g, '') // Remove quotes
                .replace(/\s+/g, ' ') // Normalize spaces
                .trim();

              // Skip if phone doesn't start with + or is too short
              if (!phone.startsWith('+') || phone.length < 10) return;

              // Get name from second column (optional)
              let name = row.length > 1 ? String(row[1] || '').trim() : null;
              if (name) {
                name = name.replace(/["']/g, '').trim();
              }

              // Extract variables if expected
              const recipientData = { phone, name };

              if (expectedVariables.length > 0) {
                recipientData.variables = {};
                const emptyVars = [];

                expectedVariables.forEach(varName => {
                  const colIndex = variableColumnIndices[varName];
                  const value = row[colIndex] !== undefined ? String(row[colIndex] || '').trim() : '';

                  if (!value) {
                    emptyVars.push(varName);
                  }
                  recipientData.variables[varName] = value;
                });

                // Check for empty variables
                if (emptyVars.length > 0) {
                  errors.push({
                    row: index + 1, // 1-based for user display
                    phone,
                    message: `Variables vacías: ${emptyVars.join(', ')}`
                  });
                }
              }

              recipients.push(recipientData);
            });

          } else {
            // Parse text file (CSV/TXT)
            const text = event.target.result;

            // Parse CSV - handle different line endings (Windows, Unix, Mac)
            const lines = text.split(/\r?\n|\r/);
            let headerParts = [];

            // If expecting variables, first line must be header
            if (expectedVariables.length > 0 && lines.length > 0) {
              headerParts = lines[0].replace(/^\uFEFF/, '').split(/[,;\t]/).map(p => p.trim());

