                }
              });

              if (missingColumns.length > 0) {
                reject(new Error(`Columnas faltantes en el archivo: ${missingColumns.join(', ')}`));
                return;
              }
            }

            for (let i = 0; i < lines.length; i++) {
              // Skip first line if it appears to be a header
              if (i === 0) {
                const lowerLine = lines[i].toLowerCase();
                if (lowerLine.includes('número') ||
                    lowerLine.includes('telefono') ||
