    const suffix = variables.length > 0 ? '_con_variables' : '';
    const fileName = `plantilla_carga_masiva${suffix}_${timestamp}.xlsx`;

    // Download file with cell format settings
    XLSX.writeFile(wb, fileName, {
      bookType: 'xlsx',
      cellStyles: true
    });
  },

